#!/usr/bin/env node

// KNOUX REC - EXE Creator Script
// سكريبت إنشاء ملف تنفيذي لـ KNOUX REC
//
// ============================ QUARANTINED ============================
// This script is kept only for reference. It generates a DIFFERENT and
// UNSAFE desktop shell than the shipped product:
//
//   * nodeIntegration: true
//   * contextIsolation: false
//   * webSecurity: false
//   * app.commandLine.appendSwitch("ignore-certificate-errors")
//   * app.commandLine.appendSwitch("disable-web-security")
//   * mainWindow.webContents.executeJavaScript(...) driven from the main process
//
// The real desktop shell lives in ../knoux-rec-app/main.cjs and is hardened
// (contextIsolation, sandbox, CSP, sender validation). Never ship the output
// of this file, and never run it in a release pipeline.
//
// Run it only if you explicitly want the legacy insecure build:
//   node legacy/create-exe.cjs --I-understand-this-is-insecure
// =====================================================================

const fs = require("fs");
const path = require("path");

const CONFIRM_FLAG = "--I-understand-this-is-insecure";

if (!process.argv.includes(CONFIRM_FLAG)) {
  console.error("This legacy generator produces an insecure Electron shell.");
  console.error("It is quarantined in legacy/ and is not part of the release path.");
  console.error(`Re-run with: node legacy/create-exe.cjs ${CONFIRM_FLAG}`);
  process.exit(2);
}

console.log("🎬 KNOUX REC - مولد الملف التنفيذي (LEGACY / INSECURE)");
console.log("=====================================");

// قراءة ملف HTML
const htmlPath = path.join(__dirname, "..", "knoux-rec-standalone.html");
if (!fs.existsSync(htmlPath)) {
  console.error("❌ لم يتم العثور على ملف knoux-rec-standalone.html");
  process.exit(1);
}

const htmlContent = fs.readFileSync(htmlPath, "utf8");

// إنشاء package.json للتطبيق الإلكتروني
const packageJson = {
  name: "knoux-rec",
  version: "1.0.0",
  description: "KNOUX REC - Professional Screen Recorder with AI",
  main: "main.js",
  scripts: {
    start: "electron .",
    build: "electron-builder",
    dist: "electron-builder --publish=never",
  },
  author: "KNOUX Team",
  license: "MIT",
  dependencies: {
    electron: "^27.0.0",
  },
  devDependencies: {
    "electron-builder": "^24.6.4",
  },
  build: {
    appId: "com.knoux.rec",
    productName: "KNOUX REC",
    directories: {
      output: "dist",
    },
    files: ["main.js", "index.html", "package.json"],
    win: {
      icon: "icon.ico",
      target: "nsis",
    },
    linux: {
      icon: "icon.png",
      target: "AppImage",
    },
    mac: {
      icon: "icon.icns",
      target: "dmg",
    },
    nsis: {
      oneClick: false,
      allowToChangeInstallationDirectory: true,
      createDesktopShortcut: true,
      createStartMenuShortcut: true,
    },
  },
};

// إنشاء ملف main.js للإلكترون
const mainJs = `
const { app, BrowserWindow, Menu, dialog, shell } = require('electron');
const path = require('path');

let mainWindow;

function createWindow() {
    mainWindow = new BrowserWindow({
        width: 1400,
        height: 900,
        minWidth: 800,
        minHeight: 600,
        icon: path.join(__dirname, 'icon.png'),
        webPreferences: {
            nodeIntegration: true,
            contextIsolation: false,
            enableRemoteModule: true,
            webSecurity: false
        },
        titleBarStyle: 'default',
        show: false
    });

    mainWindow.loadFile('index.html');

    mainWindow.once('ready-to-show', () => {
        mainWindow.show();
        
        // عرض شاشة ترحيب
        mainWindow.webContents.executeJavaScript(\`
            setTimeout(() => {
                showNotification('مرحباً بك في KNOUX REC Desktop! 🚀', 'success');
            }, 1000);
        \`);
    });

    mainWindow.on('closed', () => {
        mainWindow = null;
    });

    // منع التنقل إلى روابط خارجية
    mainWindow.webContents.on('will-navigate', (event, navigationUrl) => {
        const parsedUrl = new URL(navigationUrl);
        if (parsedUrl.origin !== 'file://') {
            event.preventDefault();
            shell.openExternal(navigationUrl);
        }
    });

    // ��عداد القائمة
    const template = [
        {
            label: 'ملف',
            submenu: [
                {
                    label: 'مشروع جديد',
                    accelerator: 'CmdOrCtrl+N',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('createProject()');
                    }
                },
                {
                    label: 'فتح المشاريع',
                    accelerator: 'CmdOrCtrl+O',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('openProjects()');
                    }
                },
                { type: 'separator' },
                {
                    label: 'خروج',
                    accelerator: process.platform === 'darwin' ? 'Cmd+Q' : 'Ctrl+Q',
                    click: () => {
                        app.quit();
                    }
                }
            ]
        },
        {
            label: 'تسجيل',
            submenu: [
                {
                    label: 'بدء التسجيل',
                    accelerator: 'F9',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('startRecording()');
                    }
                },
                {
                    label: 'إيقاف التسجيل',
                    accelerator: 'F10',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('stopRecording()');
                    }
                },
                {
                    label: 'لقطة شاشة',
                    accelerator: 'F12',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('takeScreenshot()');
                    }
                }
            ]
        },
        {
            label: 'أدوات',
            submenu: [
                {
                    label: 'قوالب الفيديو',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('openTemplates()');
                    }
                },
                {
                    label: 'أدوات الصوت',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('openAudioTools()');
                    }
                },
                {
                    label: 'التأثيرات',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('openEffects()');
                    }
                },
                {
                    label: 'الذكاء الاصطناعي',
                    click: () => {
                        mainWindow.webContents.executeJavaScript('openAI()');
                    }
                }
            ]
        },
        {
            label: 'مساعدة',
            submenu: [
                {
                    label: 'حول KNOUX REC',
                    click: () => {
                        dialog.showMessageBox(mainWindow, {
                            type: 'info',
                            title: 'حول KNOUX REC',
                            message: 'KNOUX REC - Professional Screen Recorder',
                            detail: 'مسجل الشاشة الاحترافي مع الذكاء الاصطناعي\\n\\nالإصدار: 1.0.0\\nمطور بواسطة: KNOUX Team\\n\\n© 2024 جميع الحقوق محفوظة'
                        });
                    }
                },
                {
                    label: 'اختصارات لوحة المفاتيح',
                    click: () => {
                        dialog.showMessageBox(mainWindow, {
                            type: 'info',
                            title: 'اختصارات لوحة المفاتيح',
                            message: 'الاختصارات المتاحة:',
                            detail: 'F9 - بدء/إيقاف التسجيل\\nF10 - إيقاف التسجيل\\nF12 - لقطة شاشة\\nCtrl+N - مشروع جديد\\nCtrl+O - فتح المشاريع\\nCtrl+Q - خروج'
                        });
                    }
                }
            ]
        }
    ];

    const menu = Menu.buildFromTemplate(template);
    Menu.setApplicationMenu(menu);
}

app.whenReady().then(createWindow);

app.on('window-all-closed', () => {
    if (process.platform !== 'darwin') {
        app.quit();
    }
});

app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
        createWindow();
    }
});

// منع أخطاء الشهادات في التطوير
app.commandLine.appendSwitch('ignore-certificate-errors');
app.commandLine.appendSwitch('disable-web-security');
`;

// إنشاء ملف أيقونة بسيط (SVG كـ Base64)
const iconSvg = `
<svg width="256" height="256" viewBox="0 0 256 256" xmlns="http://www.w3.org/2000/svg">
    <defs>
        <linearGradient id="grad1" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" style="stop-color:#667eea;stop-opacity:1" />
            <stop offset="100%" style="stop-color:#764ba2;stop-opacity:1" />
        </linearGradient>
    </defs>
    <rect width="256" height="256" rx="40" fill="url(#grad1)"/>
    <circle cx="128" cy="100" r="40" fill="#ff4757"/>
    <rect x="88" y="140" width="80" height="20" rx="10" fill="white"/>
    <rect x="68" y="170" width="120" height="15" rx="7" fill="white" opacity="0.8"/>
    <rect x="88" y="195" width="80" height="15" rx="7" fill="white" opacity="0.6"/>
    <text x="128" y="240" text-anchor="middle" fill="white" font-family="Arial, sans-serif" font-size="24" font-weight="bold">REC</text>
</svg>
`;

// دليل التطبيق الإلكتروني
const appDir = path.join(__dirname, "knoux-rec-app");

try {
  // إنشاء دليل التطبيق
  if (!fs.existsSync(appDir)) {
    fs.mkdirSync(appDir, { recursive: true });
  }

  // كتابة الملفات
  fs.writeFileSync(
    path.join(appDir, "package.json"),
    JSON.stringify(packageJson, null, 2),
  );
  fs.writeFileSync(path.join(appDir, "main.js"), mainJs);
  fs.writeFileSync(path.join(appDir, "index.html"), htmlContent);

  // إنشاء أيقونة PNG بسيطة (بيكسل آرت)
  const iconData = Buffer.from(
    "",
    "base64",
  );
  fs.writeFileSync(path.join(appDir, "icon.png"), iconData);

  // إنشاء ملف README
  const readmeContent = `
# KNOUX REC - Professional Screen Recorder

## وصف التطبيق
مسجل الشاشة الاحترافي مع الذكاء الاصطناعي - تطبيق سطح المكتب

## الميزات
- تسجيل الشاشة بجودة عالية
- قوالب فيديو احترافية
- أدوات تحرير متقدمة
- تأثيرات وفلاتر حقيقية
- نظام إنجازات تفاعلي
- محرك تجربة مستخدم ذكي

## كيفية التشغيل

### كتطبيق ويب:
فتح الملف \`knoux-rec-standalone.html\` في أي متصفح حديث

### كتطبيق سطح المكتب:
1. \`cd knoux-rec-app\`
2. \`npm install\`
3. \`npm start\`

### بناء ملف EXE:
1. \`cd knoux-rec-app\`
2. \`npm install\`
3. \`npm run build\`

الملف التنفيذي سيكون في مجلد \`dist\`

## اختصارات لوحة المفاتيح
- **F9**: بدء/إيقاف التسجيل
- **F10**: إيقاف التسجيل
- **F11**: إيقاف مؤقت
- **F12**: لقطة شاشة

## المطور
KNOUX Team - 2024
`;

  fs.writeFileSync(path.join(appDir, "README.md"), readmeContent);

  console.log("✅ تم إنشاء ملفات التطبيق الإلكتروني بنجاح في:", appDir);
  console.log("");
  console.log("📋 الخطوات التالية:");
  console.log("1. cd knoux-rec-app");
  console.log("2. npm install");
  console.log("3. npm start    (للتشغيل)");
  console.log("4. npm run build    (لإنشاء ملف EXE)");
  console.log("");
  console.log("📦 ملف HTML المستقل متوفر في: knoux-rec-standalone.html");
  console.log("");
} catch (error) {
  console.error("❌ خطأ في إنشاء التطبيق:", error.message);
  process.exit(1);
}
